/* @autogenerated */
import { WORKSPACE_LIST } from './workspaces.config';

describe('WORKSPACE_LIST', () => {
  it('has the 1 workspaces of the model', () => {
    expect(WORKSPACE_LIST.length).toBe(1);
  });

  it('names and places each workspace once', () => {
    expect(new Set(WORKSPACE_LIST.map((workspace) => workspace.name)).size).toBe(WORKSPACE_LIST.length);
    expect(new Set(WORKSPACE_LIST.map((workspace) => workspace.path)).size).toBe(WORKSPACE_LIST.length);
  });

  it('has at most one workspace at the root', () => {
    expect(WORKSPACE_LIST.filter((workspace) => !workspace.path).length).toBeLessThanOrEqual(1);
  });
});
